using UnityEngine;
using UnityEditor;

public class AssignIcons
{
    public static string Main()
    {
        var sb = new System.Text.StringBuilder();
        string basePath = "Assets/Herbal/";

        void AssignToItem(string assetName, string iconName)
        {
            var item = AssetDatabase.LoadAssetAtPath<InventoryItem>(basePath + assetName + ".asset");
            var icon = AssetDatabase.LoadAssetAtPath<Sprite>(basePath + iconName + ".png");
            if (item != null && icon != null)
            {
                item.icon = icon;
                EditorUtility.SetDirty(item);
                sb.AppendLine("[OK] Icon assigned for Item: " + assetName);
            }
        }

        // Assign Ingredients
        AssignToItem("Serai", "SeraiIcon");
        AssignToItem("Daun Mint", "MintIcon");
        AssignToItem("Meniran", "MeniranIcon");
        AssignToItem("Gula Aren", "ArenIcon");
        AssignToItem("Madu", "MaduIcon");

        // Assign Seeds (using same icons or generic)
        AssignToItem("Bibit Serai", "SeraiIcon");
        AssignToItem("Bibit Daun Mint", "MintIcon");
        AssignToItem("Bibit Meniran", "MeniranIcon");

        // Assign Recipes Result Items
        AssignToItem("Jamu Pegal Linu", "PegalLinuIcon");
        AssignToItem("Jamu Penyegar", "PenyegarIcon");
        AssignToItem("Wedang Herbal", "WedangHerbalIcon");
        AssignToItem("Ramuan Penurun Panas", "PenurunPanasIcon");
        AssignToItem("Jamu Stamina", "StaminaIcon");
        AssignToItem("Ramuan Anti Mual", "AntiMualIcon");
        AssignToItem("Ramuan Pernapasan", "PernapasanIcon");
        AssignToItem("Jamu Sehat Desa", "SehatDesaIcon");

        // Update Recipes Ingredients Icons
        string[] recipes = { 
            "Jamu Pegal Linu", "Jamu Penyegar", "Wedang Herbal", "Ramuan Penurun Panas", 
            "Jamu Stamina", "Ramuan Anti Mual", "Ramuan Pernapasan", "Jamu Sehat Desa" 
        };

        foreach (var r in recipes)
        {
            var recipeObj = AssetDatabase.LoadAssetAtPath<CookingRecipe>("Assets/Herbal/Recipes/" + r + ".asset");
            if (recipeObj != null && recipeObj.ingredients != null)
            {
                foreach (var ing in recipeObj.ingredients)
                {
                    var itemRef = AssetDatabase.LoadAssetAtPath<InventoryItem>(basePath + ing.itemName + ".asset");
                    if (itemRef != null)
                    {
                        ing.itemIcon = itemRef.icon;
                    }
                }
                EditorUtility.SetDirty(recipeObj);
            }
        }

        AssetDatabase.SaveAssets();
        sb.AppendLine("[SUCCESS] All Icons Assigned Successfully.");
        return sb.ToString();
    }
}
